CREATE TABLE IF NOT EXISTS "user" (
  id           TEXT PRIMARY KEY,
  email        TEXT NOT NULL UNIQUE,
  name         TEXT NOT NULL,
  image        TEXT,
  oidc_issuer  TEXT,
  oidc_subject TEXT,
  created_at   INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at   INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE UNIQUE INDEX user_oidc_identity
  ON "user" (oidc_issuer, oidc_subject)
  WHERE oidc_issuer IS NOT NULL AND oidc_subject IS NOT NULL;
CREATE TABLE oidc_session (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  issuer TEXT NOT NULL,
  subject TEXT NOT NULL,
  access_token TEXT NOT NULL,
  refresh_token TEXT,
  id_token TEXT NOT NULL,
  access_token_expires_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  created_at INTEGER NOT NULL DEFAULT (unixepoch()),
  updated_at INTEGER NOT NULL DEFAULT (unixepoch()),
  FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE
);
CREATE INDEX oidc_session_user_idx ON oidc_session (user_id);
CREATE TABLE google_oauth_state (
  id            TEXT PRIMARY KEY,
  user_id       TEXT NOT NULL,
  code_verifier TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  expires_at    TEXT NOT NULL
);
CREATE INDEX google_oauth_state_expires_idx ON google_oauth_state (expires_at);
CREATE TABLE google_connection (
  id                       INTEGER PRIMARY KEY CHECK (id = 1),
  email                    TEXT NOT NULL,
  google_user_id           TEXT NOT NULL,
  refresh_token_ciphertext TEXT NOT NULL,
  refresh_token_nonce      TEXT NOT NULL,
  encryption_key_version   INTEGER NOT NULL,
  scope                    TEXT NOT NULL,
  connected_by_user_id     TEXT NOT NULL,
  connected_at             TEXT NOT NULL,
  updated_at               TEXT NOT NULL,
  status                   TEXT NOT NULL CHECK (status IN ('connected', 'disconnected')),
  last_error               TEXT
);
CREATE TABLE meetings (
  id                 TEXT PRIMARY KEY,
  host_chapter_id    INTEGER NOT NULL,
  title              TEXT NOT NULL,
  description        TEXT NOT NULL DEFAULT '',
  start_at           TEXT NOT NULL, -- UTC ISO 8601
  end_at             TEXT NOT NULL, -- UTC ISO 8601
  time_zone          TEXT NOT NULL DEFAULT 'Asia/Tokyo',
  access_type        TEXT NOT NULL DEFAULT 'RESTRICTED'
                     CHECK (access_type IN ('RESTRICTED', 'TRUSTED', 'OPEN')),
  space_name         TEXT,
  meeting_uri        TEXT,
  meeting_code       TEXT,
  calendar_event_id  TEXT,
  calendar_html_link TEXT,
  status             TEXT NOT NULL CHECK (status IN ('creating', 'active', 'failed', 'canceled')),
  last_error         TEXT,
  created_by_user_id TEXT NOT NULL,
  created_by_email   TEXT NOT NULL,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  canceled_at        TEXT
, auto_transcription INTEGER NOT NULL DEFAULT 0 CHECK (auto_transcription IN (0, 1)), auto_smart_notes INTEGER NOT NULL DEFAULT 0 CHECK (auto_smart_notes IN (0, 1)), auto_recording INTEGER NOT NULL DEFAULT 0 CHECK (auto_recording IN (0, 1)));
CREATE INDEX meetings_space_name_idx ON meetings (space_name);
CREATE INDEX meetings_created_by_idx ON meetings (created_by_user_id);
CREATE INDEX meetings_status_start_idx ON meetings (status, start_at);
CREATE TABLE meeting_invite_sources (
  id         TEXT PRIMARY KEY,
  meeting_id TEXT NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
  kind       TEXT NOT NULL CHECK (kind IN ('host_chapter_organizers', 'chapter_organizers', 'chapter_all', 'email')),
  chapter_id INTEGER,
  email      TEXT,
  role       TEXT NOT NULL CHECK (role IN ('cohost', 'participant')),
  created_at TEXT NOT NULL
);
CREATE INDEX meeting_invite_sources_meeting_idx ON meeting_invite_sources (meeting_id);
CREATE TABLE meeting_invitees (
  meeting_id       TEXT NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
  email_normalized TEXT NOT NULL,
  email            TEXT NOT NULL,
  display_name     TEXT,
  user_id          TEXT,
  role             TEXT NOT NULL CHECK (role IN ('cohost', 'participant')),
  source_kinds     TEXT NOT NULL, google_user TEXT, -- JSON 配列: 例 ["creator", "host_chapter_organizers"]
  PRIMARY KEY (meeting_id, email_normalized)
);
CREATE INDEX meeting_invitees_email_idx ON meeting_invitees (email_normalized, meeting_id);
CREATE TABLE conference_records (
  name       TEXT PRIMARY KEY,          -- conferenceRecords/<id>
  meeting_id TEXT NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
  start_time TEXT,
  end_time   TEXT
, expire_time TEXT, stats_status TEXT NOT NULL DEFAULT 'pending'
  CHECK (stats_status IN ('pending','collecting','collected','skipped','failed','expired')), stats_attempts INTEGER NOT NULL DEFAULT 0, stats_collected_at TEXT, stats_last_error TEXT, participant_count INTEGER, invitee_attended_count INTEGER, peak_concurrent INTEGER, total_attendance_seconds INTEGER);
CREATE INDEX conference_records_meeting_idx ON conference_records (meeting_id);
CREATE TABLE artifacts (
  id                TEXT PRIMARY KEY,
  meeting_id        TEXT NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
  conference_record TEXT NOT NULL REFERENCES conference_records (name) ON DELETE CASCADE,
  kind              TEXT NOT NULL CHECK (kind IN ('recording', 'notes', 'chat_log')),
  drive_file_id     TEXT NOT NULL UNIQUE,
  title             TEXT NOT NULL,
  mime_type         TEXT NOT NULL,
  web_view_link     TEXT NOT NULL,
  created_at        TEXT NOT NULL,
  shared_at         TEXT,
  attached_at       TEXT,
  last_error        TEXT,
  attempts          INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX artifacts_meeting_idx ON artifacts (meeting_id, created_at);
CREATE INDEX artifacts_pending_idx ON artifacts (shared_at, attached_at);
CREATE TABLE processed_events (
  dedupe_key  TEXT PRIMARY KEY,         -- "<ce-type>|<resourceName>"
  received_at TEXT NOT NULL
);
CREATE TABLE google_subscription (
  id          INTEGER PRIMARY KEY CHECK (id = 1),
  name        TEXT NOT NULL,
  state       TEXT NOT NULL,
  expire_time TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  last_error  TEXT
);
CREATE TABLE drive_share_checks (
  email_normalized TEXT PRIMARY KEY,
  status           TEXT NOT NULL CHECK (status IN ('ok', 'unshareable')),
  http_status      INTEGER,
  api_status       TEXT,
  source           TEXT NOT NULL CHECK (source IN ('probe', 'share')),
  checked_at       TEXT NOT NULL
);
CREATE TABLE drive_probe_file (
  id         INTEGER PRIMARY KEY CHECK (id = 1),
  file_id    TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE artifact_share_failures (
  artifact_id      TEXT NOT NULL REFERENCES artifacts (id) ON DELETE CASCADE,
  email_normalized TEXT NOT NULL,
  http_status      INTEGER NOT NULL,
  api_status       TEXT,
  failed_at        TEXT NOT NULL,
  PRIMARY KEY (artifact_id, email_normalized)
);
CREATE INDEX conference_records_stats_idx ON conference_records (stats_status, end_time);
CREATE TABLE conference_participants (
  name TEXT PRIMARY KEY,                 -- conferenceRecords/<cr>/participants/<id>
  conference_record TEXT NOT NULL REFERENCES conference_records (name) ON DELETE CASCADE,
  meeting_id TEXT NOT NULL REFERENCES meetings (id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('signedin','anonymous','phone')),
  google_user TEXT,                      -- users/<id> (signedin only)
  display_name TEXT,
  is_host_account INTEGER NOT NULL DEFAULT 0,
  invitee_email_normalized TEXT,         -- set when google_user matches meeting_invitees.google_user
  earliest_start_time TEXT, latest_end_time TEXT,
  session_count INTEGER NOT NULL DEFAULT 0,
  total_seconds INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX conference_participants_record_idx ON conference_participants (conference_record);
CREATE TABLE conference_participant_sessions (
  name TEXT PRIMARY KEY,
  participant TEXT NOT NULL REFERENCES conference_participants (name) ON DELETE CASCADE,
  start_time TEXT, end_time TEXT
);
CREATE INDEX conference_participant_sessions_participant_idx ON conference_participant_sessions (participant);
CREATE TABLE conference_transcript_stats (
  transcript TEXT PRIMARY KEY,           -- conferenceRecords/<cr>/transcripts/<id>
  conference_record TEXT NOT NULL REFERENCES conference_records (name) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('pending','collected','failed','expired')),
  attempts INTEGER NOT NULL DEFAULT 0,
  collected_at TEXT, last_error TEXT
);
CREATE TABLE conference_speaker_stats (
  transcript TEXT NOT NULL REFERENCES conference_transcript_stats (transcript) ON DELETE CASCADE,
  participant TEXT NOT NULL,             -- participant resource name, no FK (participants may be collected later)
  entry_count INTEGER NOT NULL, char_count INTEGER NOT NULL, speaking_seconds INTEGER NOT NULL,
  PRIMARY KEY (transcript, participant)
);
